(function(root){
  'use strict'
  const photo='data:image/jpeg;base64,'
  function draw(ctx,img,s){
    ctx.fillStyle='#102B40';ctx.fillRect(0,0,2200,500)
    ctx.drawImage(img,700,0,1500,500)
    const fade=ctx.createLinearGradient(500,0,1450,0);fade.addColorStop(0,'#102B40');fade.addColorStop(1,'rgba(16,43,64,0)');ctx.fillStyle=fade;ctx.fillRect(0,0,1500,500)
    ctx.textAlign='left';ctx.textBaseline='middle'
    ctx.fillStyle='#62D8ED';ctx.font='bold 25px Arial';ctx.fillText('TASKER / EVIDENCIJA',65,68)
    ctx.fillStyle='#FFFFFF';ctx.font='bold 53px Arial';ctx.fillText('MJESEČNA EVIDENCIJA',65,145);ctx.fillText('RADNIH SATI',65,208)
    const site=s.site||'Gradilište';let size=39;while(size>16){ctx.font='bold '+size+'px Arial';if(ctx.measureText(site).width<950)break;size--}ctx.fillText(site,65,310,950)
    ctx.fillStyle='#BBD6E4';ctx.font='28px Arial';ctx.fillText(new Intl.DateTimeFormat('sr-Latn-RS',{month:'long',year:'numeric'}).format(new Date(s.month+'-15T12:00:00')).toLocaleUpperCase('sr-Latn-RS'),65,380)
    ctx.fillStyle='#143149';ctx.fillRect(1780,170,340,130)
    ctx.strokeStyle='#7396AA';ctx.lineWidth=2;ctx.strokeRect(1780,170,340,130)
    const lines=site.split(/\s*\/\s*/).filter(Boolean);ctx.textAlign='center';ctx.fillStyle='#FFFFFF'
    const lineHeight=Math.min(48,110/lines.length);size=Math.min(38,lineHeight*.8)
    while(size>10){ctx.font='bold '+size+'px Arial';if(lines.every(x=>ctx.measureText(x).width<=308))break;size--}
    lines.forEach((line,i)=>ctx.fillText(line,1950,235+(i-(lines.length-1)/2)*lineHeight,308))
    ctx.fillStyle='#38BCD6';ctx.fillRect(0,490,2200,10)
  }
  let loaded
  async function render(s){
    if(!loaded)loaded=new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>{loaded=null;reject(Error('Slika zaglavlja nije učitana. Osvježite aplikaciju.'))};img.src=photo})
    const img=await loaded,canvas=document.createElement('canvas');canvas.width=2200;canvas.height=500;draw(canvas.getContext('2d'),img,s);return canvas.toDataURL('image/png')
  }
  if(typeof module==='object'&&module.exports)module.exports={draw,photo};else root.TaskerHoursHeader={render}
})(typeof window==='object'?window:globalThis)

